async function exportedRows(selector){
 const before=await ev('window.__csvDownloads.length');await click(selector);await idle();assert.equal(await ev('window.__csvDownloads.length'),before+1);const text=await ev('window.__csvDownloads.at(-1).blob.text()');
 // Split records outside quotes, then use the source CSV cell parser per row.
 const lines=[];let quoted=false,start=0;for(let i=0;i<text.length;i++){if(text[i]==='"'){if(quoted&&text[i+1]==='"')i++;else quoted=!quoted;}if(!quoted&&text[i]==='\r'&&text[i+1]==='\n'){lines.push(text.slice(start,i+2));start=i+2;i++;}}
 return lines.slice(1).map(line=>{const [keys,cells]=parseTable(lines[0]+line);return Object.fromEntries(keys.map((key,i)=>[key.raw,cells[i].raw]));});
}
